style.css:
@-moz-document domain("youtube.com") {
/* Fondo de la página */
  body {
    background: url("https://i.pinimg.com/originals/9e/84/72/9e8472b0ac8cfdc5ef24e4b3e2d3b5e7.jpg") no-repeat center center fixed !important;
    background-size: cover !important;
  }

  /* Fondo semitransparente de los elementos */
  #page-manager, ytd-app {
    background-color: rgba(0, 0, 0, 0.5) !important;
  }

  /* Cambiar color de texto a blanco para visibilidad */
  * {
    color: white !important;
  }

  /* Ocultar el logo original de YouTube (opcional) */
  #logo-icon {
    display: none !important;
  }

  /* Personalizar la barra superior */
  ytd-masthead {
    background-color: rgba(0, 0, 0, 0.6) !important;
  }

  /* Redondear los bordes de las miniaturas */
  ytd-thumbnail, img {
    border-radius: 12px !important;
  }

  /* Efecto al pasar el mouse por los videos */
  ytd-rich-item-renderer:hover {
    background-color: rgba(255, 255, 255, 0.1) !important;
    transition: 0.3s ease-in-out;
  }
}
